  ui_story_40200001_67_dialog_content = "Amigos míos, ¿qué es exactamente el <color=#FFB400>amor</color>?",
  ui_story_40200001_68_dialog_content = "Una vez pensé que el amor era noble y reservado, pero también es caótico e incontrolable.",
  ui_story_40200001_69_dialog_content = "Como un caballo premiado que corre libre, o un vaso de licor demasiado lleno.",
