  ui_story_40200001_71_dialog_content = "Demuestra perfectamente las complejidades del amor.",
  ui_story_40200001_72_dialog_content = "Un indigente <color=#FFB400>chico de Umbraton</color> y una solitaria <color=#FFB400>chica de Umbraton</color> se enamoran, y acuerdan apoyarse mutuamente.",
  ui_story_40200001_73_dialog_content = "Pero un día, el chico de Umbraton descubre que es en verdad el <color=#FFB400>hijo ilegítimo de un noble de Lumopolis</color>.",
  ui_story_40200001_74_dialog_content = "Como si una escalera a las estrellas hubiera aterrizado de repente a sus pies, toda la fama, la riqueza y el poder que pudiera desear estaban de repente a su alcance.",
  ui_story_40200001_75_dialog_content = "La pureza y la pasión de su amor original habían empezado a desvanecerse por ello; su padre también le había conseguido una <color=#FFB400>prometida</color>.",
  ui_story_40200001_76_dialog_content = "¿A quién elegirá? ¿A la chica Umbraton que siempre ha conocido y amado? ¿O la elección de su padre, su futura novia noble?",
  ui_story_40200001_77_dialog_content = "<size=30>La chica Umbraton, ¿cierto...?</size>",
  ui_story_40200001_78_dialog_content = "¿Ah?",
  ui_story_40200001_79_dialog_content = "No es nada, olvida que dije algo...",
  ui_story_40200001_80_dialog_content = "¿Qué piensas, Sin nombre?",
  ui_story_40200001_81_option_content = "La chica Umbraton",
  ui_story_40200001_82_dialog_content = "El amor es una emoción poderosa y resistente. No se vería afectado tan fácilmente por la ganancia material.",
  ui_story_40200001_83_option_content = "La chica noble",
  ui_story_40200001_84_dialog_content = "Ya no forman parte del mismo mundo. La diferencia en su posición económica sólo terminaría por disminuir su amor mutuo.",
  ui_story_40200001_85_dialog_content = "Creo que la chica noble sería la mejor opción.",
  ui_story_40200001_86_dialog_content = "¿Así que eso es lo que piensas, hmm?",
  ui_story_40200001_87_dialog_content = "No hay una elección correcta o incorrecta. Si fuera así de simple, no habría dificultades cuando se trata de amor.",
  ui_story_40200001_88_dialog_content = "Más adelante en la historia, la chica Umbraton tropieza con <color=#FFB400>un joven noble en el desierto, y lo rescata</color>.",
  ui_story_40200001_89_dialog_content = "Este noble también desarrolla sentimientos por ella.",
  ui_story_40200001_90_dialog_content = "Cuando me salvaste la vida, me enamoré de ti a primera vista.",
  ui_story_40200001_91_dialog_content = "Pero yo...",
  ui_story_40200001_92_dialog_content = "Pero entonces, resulta que la familia de este noble y la del chico Umbraton se vieron envueltas en una <color=#FFB400>diferencia de sangre</color>...",
  ui_story_40200001_93_dialog_content = "Si fueras la chica Umbraton, ¿a quién elegirías?",
  ui_story_40200001_94_dialog_content = "<size=30>¿A quién? Uf, esto es demasiado...</size>",
  ui_story_40200001_95_dialog_content = "(Beryl parece que vuelve a murmurar para sí misma).",
  ui_story_40200001_96_option_content = "El noble",
  ui_story_40200001_97_dialog_content = "Amor a primera vista, y abandonar un viejo amor por una nueva vida... Eso también tiene sus complejidades.",
  ui_story_40200001_98_dialog_content = "Por sí solo, tendría todos los ingredientes de una buena historia... Pero no es así como esta termina realmente.",
  ui_story_40200001_99_dialog_content = "El verdadero final de la historia es que...",
  ui_story_40200001_100_dialog_content = "<color=#FFB400>La chica Umbraton y la chica noble terminan juntas.</color>",
  ui_story_40200001_101_option_content = "El chico Umbraton",
  ui_story_40200001_102_dialog_content = "Ese sería el más difícil de los dos caminos a tomar.",
  ui_story_40200001_103_dialog_content = "No sólo no recibirías nunca la bendición de la familia de tu amada, sino que tendrías que lidiar con la animosidad y la posible venganza de ambas familias durante toda tu vida.",
