  ui_story_40200001_107_dialog_content = "<color=#FFB400>Al final, la chica Umbraton y la chica noble terminan juntas.</color>",
  ui_story_40200001_108_option_content = "La chica noble",
  ui_story_40200001_109_dialog_content = "Qué elección tan poco convencional.",
  ui_story_40200001_110_dialog_content = "Dejar a un lado la moral y la ética, y no permitir que los grilletes del pasado o del presente te retengan...",
  ui_story_40200001_111_dialog_content = "<color=#FFB400>Este, de hecho, es el verdadero final de la historia.</color>",
  ui_story_40200001_112_dialog_content = "Nunca pensé que Nameless fuera tan entusiasta con este tema.",
  ui_story_40200001_113_dialog_content = "¿Eh? ¡E-Espera un seg.!",
  ui_story_40200001_114_dialog_content = "¡¿Qué demonios pasa entre ellos dos, que al final acaban juntos?!",
  ui_story_40200001_115_dialog_content = "Tendrás que encontrar la respuesta a eso... Leyendo el libro tú mismo.",
  ui_story_40200001_116_dialog_content = "Permíteme explicarte, mi querido Sin Nombre.",
  ui_story_40200001_117_dialog_content = "A esta señora no le importa el amor descrito en este libro.",
  ui_story_40200001_118_dialog_content = "Lo único que le importa son las tramas exageradas y artificiosas tan características de este tipo de historias.",
  ui_story_40200001_119_dialog_content = "Múltiples intereses amorosos, trampas, y tal vez algunos elementos sadomasoquistas para dar un toque extra.",
  ui_story_40200001_120_dialog_content = "Le sugiero encarecidamente que evite este tipo de lectura malsana, o de lo contrario su cerebro podría convertirse en papilla.",
  ui_story_40200001_121_dialog_content = "Oh, ¿qué es lo que sabes? La lectura sólo es excitante cuando se calienta y se agita así.",
  ui_story_40200001_122_dialog_content = "Creo que todos deberían echar un vistazo a mi sugerencia, en su lugar, La Vida de un Músico.",
  ui_story_40200001_123_dialog_content = "El protagonista de la historia es el Sr. Litman, el gran pianista que compuso \"La polca de Litman\".",
  ui_story_40200001_124_dialog_content = "Huérfano sin nombre, vivió una vida de soledad.",
  ui_story_40200001_125_dialog_content = "Además, su pierna derecha estaba parcialmente paralizada.",
  ui_story_40200001_126_dialog_content = "En la taberna de un pequeño pueblo sin nombre, tocó el piano durante toda su vida.",
  ui_story_40200001_127_dialog_content = "No fue hasta después de su muerte cuando se descubrieron sus hermosas composiciones y se difundieron por todo el mundo.",
  ui_story_40200001_128_dialog_content = "A pesar de que su vida fue tan sombría y desafortunada, sus obras musicales eran poderosas y edificantes.",
  ui_story_40200001_129_dialog_content = "Un trompetista con el que había colaborado dejó grabado en su lápida una sola frase:",
  ui_story_40200001_130_dialog_content = "En la música, hay vida.",
  ui_story_40200001_131_dialog_content = "Bueno, suena convincente, pero... ¿No parece que haya elementos de amor en la historia?",
  ui_story_40200001_132_dialog_content = "¿Quiere decir que no se dio cuenta de que el Sr. Litman <color=#FFB400>pasó felizmente toda su vida con su música</color>?",
  ui_story_40200001_133_dialog_content = "¡No se puede pedir un final más perfecto!",
  ui_story_40200001_134_dialog_content = "Si bien es cierto que se ve un tipo de amor en este libro, me temo que no es especialmente profundo.",
  ui_story_40200001_135_dialog_content = "Lo que sí recomendaría es este libro, \"Mil años de silencio\".",
  ui_story_40200001_136_dialog_content = "Cuenta la historia de un constructor que no puede envejecer ni morir, y cómo afronta su longevidad por sí mismo.",
  ui_story_40200001_137_dialog_content = "Tras la muerte de su última amante...",
  ui_story_40200001_138_dialog_content = "Dedica los siguientes mil años a construir un inmenso mausoleo subterráneo para sí mismo, que abarca cientos de pisos de profundidad, y finalmente cae en un profundo sueño en el fondo.",
  ui_story_40200001_139_dialog_content = "Las generaciones posteriores descubrieron la tumba del constructor y se quedaron asombradas por su exquisita artesanía. El constructor fue entonces venerado como fundador de la arquitectura.",
  ui_story_40200001_140_dialog_content = "Creo que el protagonista comprendió realmente la <color=#FFB400>esencia del amor</color>.",
  ui_story_40200001_141_dialog_content = "Abarcando tanto el tiempo como el espacio, el amor está en todas partes y, al mismo tiempo, en ninguna.",
  ui_story_40200001_142_dialog_content = "Quizá sólo algo tan firme como La Verdad pueda llamarse amor.",
  ui_story_40200001_143_dialog_content = "Ahora es tu turno, Bola de Nieve... quiero decir, Sin Nombre. Ugh, Bola de Nieve te queda mucho mejor, sin embargo...",
  ui_story_40200001_144_dialog_content = "¿M-Mi turno?",
  ui_story_40200001_145_dialog_content = "Esto es un club de lectura, después de todo, así que ahora es tu turno de compartir un libro con nosotros. O podría ser... ¿No has preparado uno?",
  ui_story_40200001_146_dialog_content = "No estamos tratando de avergonzarte ni nada, pero... ¿No has traído ningún libro?",
  ui_story_40200001_147_dialog_content = "¿Qué hay de los libros que te dio el anterior Sin Nombre? Podrías leerlos.",
  ui_story_40200001_148_dialog_content = "O-oh, sí.",
  ui_story_40200001_149_dialog_content = "Déjame ver... Espera un minuto, estos libros...",
  ui_story_40200001_150_dialog_content = "(¿\"Cómo cultivar tentáculos\"? ¿\"Mi Esqueleto Favorito\"? \"Interrogatorios y sangre: Una Historia de Amor\"???)",
  ui_story_40200001_151_dialog_content = "(Advertencia: No destinado a lectores menores de edad...)",
  ui_story_40200001_152_dialog_content = "(...)",
  ui_story_40200001_153_dialog_content = "<size=45>(¡Dulce misericordia, qué tipo de libros me has dado, Eicy!)</size>",
  ui_story_40200001_154_dialog_content = "Vamos. Comparte con el grupo.",
  ui_story_40200001_155_dialog_content = "¡No creo poder!",
  ui_story_40200001_156_dialog_content = "¡M-Mira! ¡El título de este libro ha sido incluso garabateado con un bolígrafo! ¡Seguro que no es nada que merezca la pena compartir!",
  ui_story_40200001_157_dialog_content = "Bueno, cuando se trata de sus preferencias, no puede ser nada decente.",
  ui_story_40200001_158_dialog_content = "Pero compartir es una parte necesaria de nuestro club de lectura, y Bola de Nieve no es una excepción. Ahora lee para nosotros, bien y en voz alta.",
  ui_story_40200001_159_dialog_content = "Esta es una regla inviolable del Club de Lectura de la Luna Oculta.",
  ui_story_40200001_160_dialog_content = "Yo... Yo...",
  ui_story_40200001_161_dialog_content = "Aquí, déjame...",
  ui_story_40200001_162_dialog_content = "¿Ah?",
  ui_story_40200001_163_dialog_content = "Puedo sustituir a PlayerName... Voy a compartir en su lugar.",
  ui_story_40200001_164_dialog_content = "¡Ahora, esto es una sorpresa! ¡Nunca he visto a Maiden tomar tal iniciativa!",
  ui_story_40200001_165_dialog_content = "La palabra es tuya, Maiden.",
  ui_story_40200001_166_dialog_content = "Lo que entiendo del amor es... <color=#FFB400>Romance</color>...",
  ui_story_40200001_167_dialog_content = "Comparado con lo que entienden los demás, lo mío puede parecer insignificante...",
  ui_story_40200001_168_dialog_content = "No pasa nada, di lo que quieras decir y te escucharemos.",
  ui_story_40200001_169_dialog_content = "Recomiendo este libro, \"La Arboleda Viridiana\".",
  ui_story_40200001_170_dialog_content = "Trata de un artista deprimido, que conoce a una chica de aspecto triste mientras dibuja en lo profundo del bosque.",
  ui_story_40200001_171_dialog_content = "Aunque acaba de conocerla, se enamora a primera vista...",
  ui_story_40200001_172_dialog_content = "Y comienza a dibujar a la chica con su lápiz.",
  ui_story_40200001_173_dialog_content = "Al principio, la chica se siente muy avergonzada y no quiere saber nada del artista...",
  ui_story_40200001_174_dialog_content = "Pero con el tiempo, ella empieza a ver su belleza en los dibujos del artista.",
  ui_story_40200001_175_dialog_content = "Después, empiezan a experimentar todo tipo de primicias juntos...",
  ui_story_40200001_176_dialog_content = "Y en el proceso, gradualmente crecen y superan sus imperfecciones.",
  ui_story_40200001_177_dialog_content = "...",
  ui_story_40200001_178_dialog_content = ".",
  ui_story_40200001_179_dialog_content = ".",
  ui_story_40200001_180_dialog_content = "¿No te gusta? ¿Debo elegir un libro diferente?",
  ui_story_40200001_181_dialog_content = "No, creo que es una muy buena historia.",
  ui_story_40200001_182_dialog_content = "... Oh, ¿en serio?",
  ui_story_40200001_183_dialog_content = "Beryl es aún muy joven, ¿no? Una doncella de verdad.",
  ui_story_40200001_184_dialog_content = "Las ideas de amor de los jóvenes son tan puras y felices, ¿no?",
  ui_story_40200001_185_dialog_content = "Pero no hay nada malo en eso, ¿sabes? Piensa en todas las canciones que se han escrito sobre el amor dulce e inocente.",
  ui_story_40200001_186_dialog_content = "Aunque el Sr. Litman nunca se casó en toda su vida...",
  ui_story_40200001_187_dialog_content = "compuso uno de los valses más hermosos de la historia, y se llama \"La novia alegre\".",
  ui_story_40200001_188_dialog_content = "Sólo de pensar en él, casi me dan ganas de enamorarme yo también.",
  ui_story_40200001_189_dialog_content = "Pero se necesita una pareja para el amor romántico, ¿no? ¿Un objeto de afecto?",
  ui_story_40200001_190_dialog_content = "Tenemos a Bola de Nieve, ¿no? Podríamos escribir muchas historias sobre esta lindura...",
  ui_story_40200001_191_dialog_content = "¿Eh? ¿Yo?",
  ui_story_40200001_192_dialog_content = "Sí.",
  ui_story_40200001_193_dialog_content = "¿Escribir historias sobre nuestro bronco, el Navegador? ¡Suena divertido!",
  ui_story_40200001_194_dialog_content = "Sí, incluso yo no puedo evitar estar de acuerdo.",
  ui_story_40200001_195_dialog_content = "¡Mis jugos creativos ya están fluyendo!",
  ui_story_40200001_196_dialog_content = "(Aunque todos me estén mirando...)",
  ui_story_40200001_197_dialog_content = "(Algo me dice que no van a escribir nada parecido a la historia romántica de Beryl...)",
  ui_story_40200001_198_dialog_content = "(Sino unas historias locas y bizarras que me harán enloquecer ...)",
  ui_story_40200001_199_dialog_content = "Continuará"
}
